values
  ('Student Record Management System', 1, 'Beginner (Sem 1–2)', 'Sem 1–2', 'A console program that stores student records (roll number, name, marks) in a file and can add, search, update and delete them.', 'Every university office and small school keeps student records; this is the classic first project that teaches the file handling and data organization used in real record rooms.', ARRAY['Add, edit and delete student records', 'Search by roll number or name', 'Store records permanently in a text/binary file', 'Calculate total, percentage and grade from subject marks', 'Display a class result list sorted by marks', 'Input validation so wrong entries do not crash the program'], ARRAY['C++', 'File handling (fstream)', 'Code::Blocks or VS Code', 'Git/GitHub'], 'Easy', 2, ARRAY['https://github.com/anoopsonkriya/student-management-system', 'https://github.com/XATUOS/student-information-management-system-cpp'], ARRAY['Desktop', 'Education'], 0),
  ('Library Management System — Console Edition', 1, 'Beginner (Sem 1–2)', 'Sem 1–2', 'A console app for a small library to manage books, members, and book issue/return with due dates.', 'School and college libraries in Pakistan still keep paper registers; this digitizes issue/return and shows exactly which books are out and who has them.', ARRAY['Add books with ID, title, author and number of copies', 'Register members (students and teachers)', 'Issue a book and record the due date', 'Return a book and calculate a late fine', 'Search books by title or author', 'List all currently issued books'], ARRAY['Java', 'OOP classes', 'File/CSV storage', 'IntelliJ or VS Code'], 'Easy', 2, ARRAY['https://github.com/mohanakrishnavh/library-management-system', 'https://github.com/DevAvi404/Library-Management-System'], ARRAY['Desktop', 'Education'], 1),
  ('Bank Account Management System', 1, 'Beginner (Sem 1–2)', 'Sem 1–2', 'A console banking system where users open accounts, deposit and withdraw money, and see their transaction history.', 'Banks and mobile-money agents run on exactly these operations; the project teaches OOP design (accounts as objects) plus safe balance handling.', ARRAY['Create savings and current accounts with unique account numbers', 'Deposit and withdraw with balance checks', 'Transfer money between two accounts', 'Mini statement of recent transactions', 'PIN-based login for each account', 'All data saved in files so it survives a restart'], ARRAY['C++', 'OOP (classes, inheritance)', 'File handling'], 'Medium', 3, ARRAY['https://github.com/Hifza-Khalid/Cpp-Projects'], ARRAY['Desktop', 'Finance'], 2),
  ('CGPA Calculator & Grade Tracker', 1, 'Beginner (Sem 1–2)', 'Sem 1–2', 'A small tool where students enter subject marks or grades and instantly get the GPA for each semester and the overall CGPA on the 4.0 scale.', 'Pakistani university students calculate GPA/CGPA by hand every semester and often get it wrong; this follows the HEC-style grading scale used by local universities.', ARRAY['Add subjects with credit hours and marks', 'Automatic grade and grade-point conversion (HEC scale)', 'Semester GPA and cumulative CGPA calculation', 'Save multiple semesters and view history', 'Target calculator: what GPA is needed next semester to reach a goal CGPA', 'Works fully offline'], ARRAY['HTML/CSS/JavaScript', 'Browser local storage'], 'Easy', 2, ARRAY['https://github.com/knoxiboy/CGPA-Calculator', 'https://github.com/rishav-dahal/CGPA-Calculator'], ARRAY['Web', 'Education'], 3),
  ('Quiz App with Timer & Scoreboard', 1, 'Beginner (Sem 1–2)', 'Sem 1–2', 'A desktop quiz application that asks multiple-choice questions with a countdown timer and shows the final score.', 'Teachers need quick class tests and students need practice tools; building it teaches GUI windows, events and working with question data.', ARRAY['Load questions from a JSON or text file', 'Four-option MCQs with instant right/wrong feedback', 'Per-question countdown timer', 'Score tracking with a final result screen', 'Category-wise quizzes (e.g. Programming, DLD, Maths)', 'Questions and options shuffled on every attempt'], ARRAY['Python', 'Tkinter', 'JSON'], 'Easy', 2, ARRAY['https://github.com/yogendra-08/trivia-quiz-stats-app', 'https://github.com/iam-abhijha/Quiz_app_tkinter'], ARRAY['Desktop', 'Education'], 4),
  ('Personal Expense Tracker', 1, 'Beginner (Sem 1–2)', 'Sem 1–2', 'A command-line app to record daily expenses (kharcha) by category and see weekly and monthly summaries.', 'Students living in hostels need to control monthly spending on food, transport and mobile recharge; this turns scattered spending into clear totals.', ARRAY['Add expenses with date, category and amount in PKR', 'View today''s, weekly and monthly totals', 'Category-wise summary (food, transport, bills, other)', 'Data stored permanently in SQLite', 'Edit or delete wrong entries', 'Export the monthly report to a CSV file'], ARRAY['Python', 'SQLite3', 'CSV export'], 'Easy', 2, ARRAY['https://github.com/daemonlabs-pixel/Personal-Expense-Tracker', 'https://github.com/LakinduQA/spendly-finance_tracker'], ARRAY['Desktop', 'Data', 'Finance'], 5),
  ('Snake Game', 1, 'Beginner (Sem 1–2)', 'Sem 1–2', 'The classic snake game where the snake grows as it eats food, with score, levels and game-over detection.', 'A first game project that teaches the game loop, keyboard input, collision detection and real-time drawing — the base of all game development.', ARRAY['Smooth snake movement with arrow keys', 'Food spawning and snake growth', 'Score and saved high score', 'Speed increases as the score grows', 'Wall and self-collision game over', 'Pause and restart options'], ARRAY['Python', 'Pygame'], 'Easy', 2, ARRAY['https://github.com/hammadfarooq-ai/Snake-Game', 'https://github.com/siriusberg/SnakeGame'], ARRAY['Desktop', 'Game Development'], 6),
  ('Typing Speed Test', 1, 'Beginner (Sem 1–2)', 'Sem 1–2', 'A desktop app that measures typing speed (words per minute) and accuracy on random paragraphs.', 'Good typing speed matters for programming students and office jobs; online typing tests need internet and accounts — this works offline for free.', ARRAY['Random paragraph selection (English; Roman Urdu paragraphs as a stretch goal)', 'Live WPM and accuracy calculation', 'Correct and wrong characters highlighted while typing', '1-minute and 3-minute test modes', 'Result history to see improvement over time'], ARRAY['Python', 'Tkinter'], 'Easy', 2, ARRAY['https://github.com/PiyushRaj714/Typing-speed-test', 'https://github.com/basanta-bhandari/Pytype'], ARRAY['Desktop', 'Education'], 7),
  ('Kiryana Store Billing System', 1, 'Beginner (Sem 1–2)', 'Sem 1–2', 'A console billing system for a small grocery (kiryana) shop that prepares customer bills with item prices in rupees.', 'Thousands of small shops in Sindh and Punjab still write bills on paper and make total mistakes; this gives fast, error-free bills and a daily sales total.', ARRAY['Item price list (atta, cheeni, chawal and more) with price per kg or per piece', 'Add items to a bill with quantity', 'Automatic total, discount and change calculation', 'Save the bill as a text receipt', 'End-of-day sales report (total kamai)', 'Price list editable from a simple file'], ARRAY['C++ or Java', 'File handling for the price list'], 'Easy', 2, ARRAY['https://github.com/jawadshahid07/POS-System'], ARRAY['Desktop', 'Business'], 8),
  ('Password-Protected Personal Diary', 1, 'Beginner (Sem 1–2)', 'Sem 1–2', 'A private diary app where entries are locked with a password and stored encrypted on your own computer.', 'People want a journal nobody else can read; the project teaches basic security — password hashing and encryption — inside a small, real application.', ARRAY['Master password stored hashed, never in plain text', 'Write, view and edit dated diary entries', 'Entries encrypted before saving (Fernet/AES)', 'Search entries by date or keyword after unlocking', 'Everything stays offline on your own machine'], ARRAY['Python', 'cryptography library (Fernet)', 'File storage'], 'Medium', 3, ARRAY['https://github.com/siddharth94/secure-journal', 'https://github.com/sinhaayush61426-ai/mindvault'], ARRAY['Desktop', 'Security'], 9),
  ('Tic-Tac-Toe with Computer Opponent', 1, 'Beginner (Sem 1–2)', 'Sem 1–2', 'The classic X/O game against the computer, including an unbeatable mode powered by the minimax algorithm.', 'It is the simplest real introduction to AI thinking — the computer plans moves ahead — inside a game every beginner can actually finish.', ARRAY['Play against a friend (2-player) or against the computer', 'Easy mode (random moves) and hard mode (minimax — never loses)', 'Win and draw detection with the winning line shown', 'Scoreboard across multiple rounds', 'Console version first, Tkinter GUI as an upgrade'], ARRAY['Python', 'Minimax algorithm', 'Tkinter (optional GUI)'], 'Medium', 2, ARRAY['https://github.com/TheAlgorithms/Python'], ARRAY['Desktop', 'Game Development', 'AI/ML'], 10),
  ('Inventory Management System with MySQL', 2, 'Intermediate (Sem 3–4)', 'Sem 3–4', 'A database-backed system for a shop or warehouse to track stock, purchases and sales so nothing runs out silently.', 'Local wholesalers and mobile shops lose money when stock is tracked in notebooks; this shows real stock levels, low-stock alerts and complete sales history.', ARRAY['Products with categories, cost price and sale price', 'Purchase entries that increase stock', 'Sales entries that decrease stock automatically', 'Low-stock warning list', 'Search and filter products', 'Monthly sales and profit reports'], ARRAY['Java or PHP', 'MySQL', 'JDBC or phpMyAdmin', 'XAMPP'], 'Medium', 4, ARRAY['https://github.com/AsjadIqbal/InventoryManagementSystem', 'https://github.com/RobertasKirkickas/inventory-management-system-java'], ARRAY['Desktop', 'Web', 'Data'], 11),
  ('Sorting Algorithm Visualizer', 2, 'Intermediate (Sem 3–4)', 'Sem 3–4', 'A visual tool that animates how sorting algorithms (bubble, merge, quick, heap) arrange bars step by step.', 'DSA students cannot ''see'' how algorithms work from book diagrams; watching them move makes time complexity and algorithm behaviour obvious.', ARRAY['Animate bubble, selection, insertion, merge, quick and heap sort', 'Adjustable array size and animation speed', 'Step counter and comparison counter for each algorithm', 'Random, nearly-sorted and reversed input modes', 'Race mode: two algorithms side by side (stretch goal)'], ARRAY['JavaScript', 'HTML Canvas', 'CSS'], 'Medium', 3, ARRAY['https://github.com/Czar-16/Sorting-Visualizer', 'https://github.com/qkanji/SortingVisual'], ARRAY['Web', 'Education'], 12),
  ('Pathfinding Visualizer (A*, Dijkstra, BFS, DFS)', 2, 'Intermediate (Sem 3–4)', 'Sem 3–4', 'An interactive grid where you draw walls and watch A*, Dijkstra, BFS and DFS find the shortest path.', 'Graph algorithms are the heart of DSA and of real systems like map routing; this makes search behaviour visible and directly comparable.', ARRAY['Draw walls and obstacles with the mouse', 'Place start and target points anywhere', 'Run A*, Dijkstra, BFS, DFS and Greedy Best-First with animation', 'Visited-node count and path length shown for comparison', 'Random maze generation', 'Clear and reset grid'], ARRAY['JavaScript', 'HTML/CSS'], 'Medium', 3, ARRAY['https://github.com/clementmihailescu/Pathfinding-Visualizer', 'https://github.com/btschneid/Pathfinding-and-Sorting-Visualizer'], ARRAY['Web', 'Education'], 13),
  ('LAN Chat Application with Sockets', 2, 'Intermediate (Sem 3–4)', 'Sem 3–4', 'A real-time chat app where many users on the same network send messages through a central server program.', 'Hostels, computer labs and offices often need local chat without internet; building it teaches networking (sockets and threads), which is core computer science.', ARRAY['Server handles many clients at once using threads', 'Public group chat plus private one-to-one messages', 'Usernames and an online-user list', 'Message timestamps', 'Works on a local network with no internet', 'Simple GUI client (Java Swing or Python Tkinter)'], ARRAY['Java (Sockets, Threads) or Python (socket, threading)', 'Swing or Tkinter'], 'Medium', 4, ARRAY['https://github.com/PrakhyatKhati/chatApp_Java', 'https://github.com/Kavithma-Thushal/ChatApplication'], ARRAY['Desktop', 'Networking'], 14),
  ('Intercity Bus Ticket Booking System', 2, 'Intermediate (Sem 3–4)', 'Sem 3–4', 'A booking system for intercity buses (for example Larkana–Karachi routes) with seat selection, schedules and ticket records stored in a database.', 'Passengers still queue at bus addas or depend on agents; a digital seat map and booking record removes double-booking and confusion.', ARRAY['Routes, buses and departure schedules managed by an admin', 'Visual seat map — pick your own seat', 'Passenger booking with name and phone number', 'Bookings stored in a database with ticket numbers', 'Cancel a booking and free the seat', 'Daily departure list and booked-seat report'], ARRAY['Python Django', 'PostgreSQL or SQLite', 'HTML/Tailwind CSS'], 'Medium', 5, ARRAY['https://github.com/JunaidSalim/GIKI_Bus_Ticket_Reservation_System', 'https://github.com/AyanSrivastava11/python_Project--Bus-Booking'], ARRAY['Web', 'Transport', 'Data'], 15),
  ('Hospital Management System (PHP + MySQL)', 2, 'Intermediate (Sem 3–4)', 'Sem 3–4', 'A web system for a small hospital or clinic to manage patients, doctors, appointments and billing.', 'Small hospitals and clinics in Pakistan manage OPD slips and patient files on paper; this keeps searchable records and smooth, token-based appointments.', ARRAY['Patient registration with medical history', 'Doctor list with specialization and duty timings', 'Appointment booking with token numbers', 'OPD visit records and prescriptions', 'Billing for consultation and lab tests', 'Admin dashboard with daily patient count'], ARRAY['PHP', 'MySQL', 'HTML/CSS/Bootstrap', 'XAMPP'], 'Medium', 5, ARRAY['https://github.com/ahsanrizvi99/hospital-patient-management-system', 'https://github.com/sanjana1194/Hospital-Management-System'], ARRAY['Web', 'Healthcare'], 16),
  ('Online MCQ Exam System', 2, 'Intermediate (Sem 3–4)', 'Sem 3–4', 'A web exam system where teachers create MCQ tests and students attempt them online with automatic marking.', 'Schools and academies spend hours checking objective papers; auto-marking gives students instant results and teachers ready class reports.', ARRAY['Teacher panel to add subjects, questions and answer keys', 'Student login with a one-attempt exam rule', 'Exam timer with auto-submit', 'Instant result with correct answers shown', 'Class result list and top-scorer report', 'Question bank stored in MySQL'], ARRAY['PHP', 'MySQL', 'HTML/CSS/JavaScript', 'XAMPP'], 'Medium', 4, ARRAY['https://github.com/SarveshMankar/MCQ-Examination'], ARRAY['Web', 'Education'], 17),
  ('File Compressor using Huffman Coding', 2, 'Intermediate (Sem 3–4)', 'Sem 3–4', 'A tool that compresses text files using Huffman coding and decompresses them back without losing a single character.', 'It is the real algorithm behind ZIP-style compression; building it teaches trees, priority queues and bit-level file work in one project.', ARRAY['Build a Huffman tree from character frequencies', 'Compress a text file into a smaller binary file', 'Decompress back to the exact original text', 'Show original vs compressed size and saving percentage', 'Code table saved inside the compressed file', 'Handles English and Urdu mixed UTF-8 text files'], ARRAY['C++ or Java', 'Priority queue', 'Bit manipulation'], 'Hard', 4, ARRAY['https://github.com/Arshia-Sharifi/File-Compression', 'https://github.com/seanwu1105/adaptive-huffman-coding'], ARRAY['Desktop', 'Data'], 18),
  ('Event Ticket Booking System with Transactions', 2, 'Intermediate (Sem 3–4)', 'Sem 3–4', 'A web app to book tickets for movies, concerts and matches, using proper database transactions so a seat is never sold twice.', 'It teaches the hardest part of real booking systems — transactions, triggers and stored procedures — on a fun, easy-to-understand problem.', ARRAY['Browse events (movies, concerts, matches) with dates and prices', 'Book tickets through a stored procedure (all-or-nothing transaction)', 'Ticket counts updated automatically with triggers', 'Customer accounts and booking history', 'Payment record linked to every booking', 'Admin panel for events and sales'], ARRAY['Python Flask', 'MySQL (stored procedures, triggers)', 'HTML/CSS'], 'Hard', 5, ARRAY['https://github.com/Sinchanacsajjanashettar/Event_Ticket_Booking_System'], ARRAY['Web', 'Data'], 19),
  ('Library Management System — Web Edition', 2, 'Intermediate (Sem 3–4)', 'Sem 3–4', 'A full web library system with member accounts, an online book catalog, barcode-based issue/return and automatic fines.', 'The grown-up version of the Semester 1 console project: university libraries need exactly this — a searchable catalog, who has which book, and automatic fine calculation.', ARRAY['Online book catalog with search by title, author or ISBN', 'Separate student and librarian roles with login', 'Issue and return using book barcode/ID', 'Automatic overdue fine calculation', 'Reservation queue when a book is issued out', 'Reports: most-issued books and defaulter list'], ARRAY['Java Spring Boot', 'React', 'MySQL'], 'Hard', 6, ARRAY['https://github.com/mignotD/LibTrack'], ARRAY['Web', 'Education'], 20),
  ('Personal Finance Dashboard', 2, 'Intermediate (Sem 3–4)', 'Sem 3–4', 'A web dashboard that turns income and expenses into charts, category budgets and monthly insights.', 'The web upgrade of the console expense tracker: students and families can see where the money goes each month and whether they stayed within budget.', ARRAY['Add income and expenses with categories', 'Monthly budget limit per category with overspend warnings', 'Pie and bar charts of spending', 'Filter by month and category', 'User accounts with data stored in SQLite', 'Export the report as CSV'], ARRAY['Python Flask', 'SQLite', 'Chart.js', 'HTML/CSS'], 'Medium', 4, ARRAY['https://github.com/Parth-10101/expense-tracker-python'], ARRAY['Web', 'Data', 'Finance'], 21),
  ('AI Study Assistant — Chat with Your Notes (RAG)', 3, 'Advanced (Sem 5–6)', 'Sem 5–6', 'An AI assistant where students upload lecture notes and PDFs and ask questions; the answers come from their own study material.', 'Students drown in PDFs before exams; an assistant that answers only from their course material, showing the source it used, saves hours and avoids made-up answers.', ARRAY['Upload PDFs/notes and build a searchable index (embeddings)', 'Ask questions in natural language', 'Answers grounded in the uploaded documents with source chunks shown', 'Separate chat history per subject', 'One-click summary of any chapter', 'Runs on a free Gemini API key'], ARRAY['Python', 'Streamlit', 'LangChain', 'Gemini API', 'FAISS or ChromaDB'], 'Hard', 6, ARRAY['https://github.com/NadiaNova/personal-ai-assistant-with-memory', 'https://github.com/KayvanShah1/VirtuTA'], ARRAY['AI/ML', 'Web', 'Education'], 22),
  ('E-Commerce Store with Product Recommendations', 3, 'Advanced (Sem 5–6)', 'Sem 5–6', 'A full online store with cart, checkout and a recommendation section that suggests products based on what a user viewed or bought.', 'Online shopping is growing fast in Pakistan and local sellers need affordable stores; recommendations are what make big stores sell more.', ARRAY['Product catalog with categories, search and filters', 'Cart and checkout flow with order placement', 'User accounts with order history', 'Admin panel for products, orders and users', '''You may also like'' recommendations from browsing and purchase data', 'Product reviews and ratings'], ARRAY['MongoDB', 'Express', 'React', 'Node.js (MERN)', 'JWT authentication'], 'Hard', 8, ARRAY['https://github.com/bradtraversy/proshop-v2', 'https://github.com/damesh13/shopez-one-stop-shop-for-online-purchases'], ARRAY['Web', 'AI/ML'], 23),
  ('Smart Attendance System with Face Recognition', 3, 'Advanced (Sem 5–6)', 'Sem 5–6', 'A system that marks student attendance automatically by recognizing faces from a classroom photo or webcam.', 'Teachers waste 10–15 minutes daily on manual attendance; automatic marking with a photo record also stops proxy attendance.', ARRAY['Register students with a few photos each', 'Detect and recognize many faces in a single class photo', 'Mark present/absent in a database with date and time', 'Daily and per-student attendance reports', 'Unknown faces flagged for the teacher to review', 'Works with a normal laptop webcam'], ARRAY['Python', 'OpenCV', 'face_recognition (dlib)', 'Flask', 'SQLite or MySQL'], 'Hard', 6, ARRAY['https://github.com/Nikshay-Jain/Prosence', 'https://github.com/FriedricNietzsche/Face-Recognition-Based-Attendance-System'], ARRAY['AI/ML', 'Desktop', 'Education'], 24),
  ('Plagiarism Checker for Assignments', 3, 'Advanced (Sem 5–6)', 'Sem 5–6', 'A tool that compares a student''s assignment against other submissions and reference text and reports similarity with the copied parts highlighted.', 'Copy-paste assignments are a real problem in universities; teachers need a quick similarity report instead of reading the same text many times.', ARRAY['Upload or paste assignment text', 'Compare one document against a whole class set', 'Similarity percentage for every document pair', 'Matching sentences highlighted side by side', 'Supports .txt and .docx files', 'Class report ranking the most similar submissions'], ARRAY['Python', 'scikit-learn (TF-IDF, cosine similarity)', 'Flask or Streamlit'], 'Medium', 5, ARRAY['https://github.com/architshukla/Plagiarism-Checker', 'https://github.com/irgifebry/plagiarism-checker'], ARRAY['AI/ML', 'Web', 'Education'], 25),
  ('Job & Internship Portal for Students', 3, 'Advanced (Sem 5–6)', 'Sem 5–6', 'A portal where companies post jobs and internships and students apply with profiles and CVs.', 'Fresh graduates in smaller cities like Larkana miss opportunities that circulate only in big-city networks; a focused portal connects them directly with employers.', ARRAY['Company accounts to post jobs and internships', 'Student profiles with skills and CV upload', 'Search and filter by city, job type and skills', 'Apply with one click and track application status', 'Admin approval of companies and job posts', 'Status notifications for applicants (stretch goal)'], ARRAY['MongoDB', 'Express', 'React', 'Node.js (MERN)', 'JWT authentication'], 'Hard', 7, ARRAY['https://github.com/HafizMuhammad-Saad/MERN-job-portal', 'https://github.com/ashikulislamcse/MERN-stack-Job-Portal'], ARRAY['Web'], 26),
  ('Symptom-Based Disease Prediction System', 3, 'Advanced (Sem 5–6)', 'Sem 5–6', 'A web app where a user selects symptoms and a machine-learning model suggests the most likely disease along with precautions.', 'In rural areas the nearest doctor can be hours away; a first-level guidance tool helps people judge how urgent their problem is. It is guidance only, not a diagnosis.', ARRAY['Select symptoms from a searchable list', 'ML model (Random Forest / Decision Tree) predicts the likely disease', 'Disease description and precautions shown with the result', 'Top-3 possible diseases with confidence scores', 'Simple, mobile-friendly interface', 'Clear disclaimer to consult a doctor'], ARRAY['Python', 'scikit-learn', 'Flask or Streamlit', 'Kaggle symptom-disease dataset'], 'Medium', 5, ARRAY['https://github.com/GauraviVeling/MedicalDiagnosisSystem', 'https://github.com/amMistic/Diseases-Prediction-based-on-Symptoms'], ARRAY['AI/ML', 'Web', 'Healthcare'], 27),
  ('Crop & Plant Disease Detection (CNN)', 3, 'Advanced (Sem 5–6)', 'Sem 5–6', 'A mobile-friendly web app where a farmer photographs a leaf and a CNN model identifies the crop disease.', 'Sindh''s farmers lose crops to diseases they cannot identify early; a photo-based check at the right time can save a whole season''s income.', ARRAY['Upload or capture a leaf photo', 'CNN model trained on the PlantVillage dataset', 'Disease name shown with a confidence score', 'Treatment and prevention guidance for each disease', 'Covers common crop classes from the dataset (tomato, potato, corn and more)', 'Simple interface that works on low-end phones'], ARRAY['Python', 'TensorFlow/Keras (CNN, transfer learning)', 'Flask', 'PlantVillage dataset'], 'Hard', 6, ARRAY['https://github.com/Ashutoshh21/Plant-Disease-Detection', 'https://github.com/Shyam-Sundar-Raju/Plant_disease_detection'], ARRAY['AI/ML', 'Web', 'Agriculture'], 28),
  ('IoT Smart Agriculture Monitoring System', 3, 'Advanced (Sem 5–6)', 'Sem 5–6', 'Sensors in the field send soil moisture, temperature and humidity to a live dashboard so farmers water crops only when needed.', 'Water is scarce in Sindh and tube-wells cost diesel or electricity; watering by sensor data instead of guesswork saves both water and money.', ARRAY['ESP32/ESP8266 reads soil moisture, temperature and humidity (DHT11 sensor)', 'Live dashboard with current readings and history charts', 'Low-moisture alert on the dashboard', 'Automatic pump ON/OFF rules based on moisture level', 'Data stored in a free cloud database (Firebase or ThingSpeak)', 'Low-cost hardware list suitable for a student budget'], ARRAY['ESP32/Arduino (C++)', 'DHT11 and soil-moisture sensors', 'Firebase or MQTT', 'Web dashboard (HTML/React)'], 'Hard', 7, ARRAY['https://github.com/ayushchahat/Smart_Agro', 'https://github.com/ThatOneCoderWhoCreates/smart-agriculture-iot'], ARRAY['IoT', 'Agriculture', 'Web'], 29),
  ('Roman Urdu Sentiment Analysis', 3, 'Advanced (Sem 5–6)', 'Sem 5–6', 'An ML tool that reads Roman Urdu comments and reviews and classifies them as positive, negative or neutral.', 'Most Pakistani social-media text is written in Roman Urdu, which English sentiment tools cannot understand; brands, researchers and content creators need local-language analysis.', ARRAY['Train on a public Roman Urdu sentiment dataset (100k+ labelled sentences available)', 'Preprocessing that handles spelling variations (acha / achha / achaa)', 'Classifier with a proper accuracy report (Naive Bayes, Logistic Regression)', 'Paste a single comment or upload a file for batch results', 'Word clouds of positive and negative comments', 'Simple web demo built with Streamlit'], ARRAY['Python', 'scikit-learn', 'NLTK', 'pandas', 'Streamlit'], 'Medium', 5, ARRAY['https://github.com/Khubaib8281/RomanUrdu-NLP', 'https://github.com/saman-azhar/multilingual-sentiment-classifier'], ARRAY['AI/ML', 'Data'], 30),
  ('AI Traffic Monitoring & Vehicle Counting', 3, 'Advanced (Sem 5–6)', 'Sem 5–6', 'A computer-vision system that watches road video, detects vehicles and counts them by type, with speed estimates.', 'Traffic police and city planners in Pakistan rely on manual counting; automatic counting from recorded road footage gives real data for signal timing and road planning.', ARRAY['Detect cars, bikes, rickshaws, trucks and buses with YOLOv8', 'Count vehicles crossing a virtual line (in and out)', 'Track each vehicle across frames', 'Estimate the speed of each vehicle', 'Dashboard with per-hour traffic graphs', 'Works on recorded video files — no live camera needed'], ARRAY['Python', 'YOLOv8 (Ultralytics)', 'OpenCV', 'Streamlit'], 'Hard', 6, ARRAY['https://github.com/Divyanshu18-code/ai-traffic-monitoring-system', 'https://github.com/Incredible-T/vehicle-detection-and-counting'], ARRAY['AI/ML', 'Data'], 31),
  ('Social Learning Platform for Students', 3, 'Advanced (Sem 5–6)', 'Sem 5–6', 'A social web app where students share study posts, notes and resources and follow each other — a study-focused social network.', 'Useful material gets buried in class WhatsApp groups; a dedicated platform keeps notes, questions and discussions organized and searchable.', ARRAY['Student accounts with profiles', 'Create posts with text and images (notes, questions)', 'Like, comment and save posts', 'Follow classmates and see a personal feed', 'Search posts by subject or topic tags', 'Edit and delete your own posts'], ARRAY['MongoDB', 'Express', 'React', 'Node.js (MERN)', 'JWT authentication', 'Cloudinary (free tier)'], 'Hard', 7, ARRAY['https://github.com/adrianhajdin/project_mern_memories'], ARRAY['Web', 'Education'], 32),
  ('AI-Based Online Exam Proctoring System', 4, 'FYP-grade (Sem 7–8)', 'Sem 7–8', 'A proctoring system that watches students during online exams through the webcam and flags suspicious behaviour automatically.', 'Online exams are now common but cheating is easy; universities need affordable proctoring that flags an absent face, multiple faces or phone use for teacher review.', ARRAY['Face-presence and multiple-face detection during the exam', 'Head-pose and gaze-deviation warnings', 'Mobile phone / extra object detection in the frame', 'Warning counter with automatic exam submit at the limit', 'Timestamped incident log with screenshots for the teacher', 'Post-exam integrity report for every student'], ARRAY['Python', 'OpenCV', 'MediaPipe or YOLO', 'Flask', 'React'], 'Hard', 12, ARRAY['https://github.com/royan04/online-exam-proctoring-system', 'https://github.com/Kapil1071/AI-Based-Online-Exam-Cheating-Detection'], ARRAY['AI/ML', 'Web', 'Education'], 33),
  ('Integrated Hospital Management System with Analytics', 4, 'FYP-grade (Sem 7–8)', 'Sem 7–8', 'A complete hospital platform — patients, doctors, wards, pharmacy, lab and billing — with management dashboards and reports.', 'District-level hospitals run on paper and disconnected registers; one system with analytics shows bed occupancy, revenue and disease trends so management can make better decisions.', ARRAY['Modules for OPD, admissions and wards, pharmacy stock and lab reports', 'Role-based access (admin, doctor, receptionist, pharmacist)', 'Complete patient journey from registration to discharge bill', 'Analytics dashboard: daily patients, revenue, common diseases', 'Video-consultation module as a stretch goal', 'Backup and audit logs'], ARRAY['MongoDB/Express/React/Node or Django + PostgreSQL', 'Chart.js', 'JWT role-based access'], 'Hard', 14, ARRAY['https://github.com/TS-Anusha27/healthverse', 'https://github.com/Markcus0526/ife-hospital-webrtc-web'], ARRAY['Web', 'Healthcare', 'Data'], 34),
  ('Telemedicine Platform for Rural Areas', 4, 'FYP-grade (Sem 7–8)', 'Sem 7–8', 'A platform where rural patients book video consultations with city doctors, with digital prescriptions and medical records.', 'Villages around Larkana have basic health units but no specialists; a video consultation saves a full day of travel for a fifteen-minute check-up.', ARRAY['Patient and doctor registration with verification', 'Search doctors by specialization and book time slots', 'Video consultation (WebRTC / Agora free tier)', 'Digital prescription after every consultation', 'Patient medical history kept in one place', 'Low-bandwidth friendly design with an Urdu interface option'], ARRAY['Next.js or React', 'Node.js', 'MongoDB', 'WebRTC (Agora or Jitsi free tier)'], 'Hard', 12, ARRAY['https://github.com/MMansy19/Telemedicine-App', 'https://github.com/PratikMane0112/TelMedSphere'], ARRAY['Web', 'Healthcare', 'Mobile'], 35),
  ('Sindhi & Urdu Language Learning App', 4, 'FYP-grade (Sem 7–8)', 'Sem 7–8', 'A mobile app that teaches Sindhi and Urdu to children and non-native speakers with lessons, audio and quizzes in proper right-to-left script.', 'Popular language apps ignore Pakistani languages; children in big cities and overseas Pakistanis are losing touch with Sindhi and Urdu script and speaking.', ARRAY['Structured lessons: alphabets, words, then sentences', 'Audio pronunciation for every word', 'RTL interface with proper Nastaliq / Sindhi script fonts', 'Quizzes and flashcards with progress tracking', 'Daily streak and level system', 'Offline lesson downloads for low-connectivity areas'], ARRAY['Flutter', 'Firebase or Supabase', 'Text-to-speech package'], 'Hard', 12, ARRAY['https://github.com/Aqsa-khan745/Rehbar-AI-Assistant', 'https://github.com/totallyalien/Language-Learning-App'], ARRAY['Mobile', 'Education'], 36),
  ('Flood Relief & Disaster Coordination Platform', 4, 'FYP-grade (Sem 7–8)', 'Sem 7–8', 'A platform that collects flood-victim help requests, maps affected areas and coordinates relief teams, shelters and supplies.', 'The 2022 Sindh floods showed that relief fails without coordination — duplicate aid in one village and none in the next; this gives NGOs and authorities one shared picture.', ARRAY['Victims and field workers report needs (food, shelter, medical) with location', 'Live map of incidents, shelters and supply centres', 'Rescue-team tracking and task assignment', 'Relief inventory with low-stock alerts', 'Simple reporting flow designed for weak-internet areas', 'Admin command dashboard with a priority queue'], ARRAY['React', 'Node.js + MongoDB or Django', 'Leaflet / OpenStreetMap', 'PWA'], 'Hard', 12, ARRAY['https://github.com/FlamingRanger/Aapda-Saarthi', 'https://github.com/ChalanaDilshan/resq-lanka'], ARRAY['Web', 'Mobile', 'Data'], 37),
  ('University Knowledge Assistant (RAG Chatbot)', 4, 'FYP-grade (Sem 7–8)', 'Sem 7–8', 'An AI chatbot trained on a university''s own documents — prospectus, rules, fee structure, past papers — that answers student questions with sources.', 'Students ask the same questions every semester and admin offices are overloaded; a grounded chatbot answers instantly and only from official documents.', ARRAY['Ingest PDFs and Word documents (rules, prospectus, timetables) into a vector database', 'Answers with citations to the exact document section', 'Questions supported in English and Urdu', 'Admin panel to update documents without coding', 'Feedback button to catch and fix wrong answers', 'Deployable as a website widget plus a standalone page'], ARRAY['Python', 'LangChain', 'Gemini API', 'ChromaDB or FAISS', 'FastAPI', 'React'], 'Hard', 10, ARRAY['https://github.com/pixegami/rag-tutorial-v2', 'https://github.com/NirDiamant/RAG_Techniques'], ARRAY['AI/ML', 'Web', 'Education'], 38),
  ('University Admission Merit Predictor', 4, 'FYP-grade (Sem 7–8)', 'Sem 7–8', 'An ML system that predicts a student''s admission chances and merit position using matric, intermediate and entry-test marks.', 'Pakistani students apply almost blindly, without knowing where their aggregate stands; a predictor trained on past merit lists shows realistic chances for each university and program.', ARRAY['Aggregate calculated by the standard formula (Matric 10% + Inter 40% + Entry Test 50%)', 'ML model trained on previous years'' merit data', 'Admission-chance prediction per university and program', 'Reverse calculator: what entry-test score do I need for this program?', 'Side-by-side comparison of programs', 'Admin can upload new merit lists every year'], ARRAY['Python', 'scikit-learn', 'Flask', 'pandas'], 'Hard', 10, ARRAY['https://github.com/dyavadi8769/University_Admission_Prediction', 'https://github.com/KathanSheth/Student-Admission-Prediction-with-Machine-Learning'], ARRAY['AI/ML', 'Web', 'Education', 'Data'], 39),
  ('Smart Crop Advisory System for Sindh Farmers', 4, 'FYP-grade (Sem 7–8)', 'Sem 7–8', 'A system that recommends crops, fertilizer and irrigation timing from soil, weather and market data — with a voice interface in Sindhi and Urdu.', 'Farmers choose crops by tradition while soil conditions, weather and prices keep changing; data-based advice in their own language can raise income per acre.', ARRAY['Crop recommendation model from soil NPK, pH, rainfall and temperature', 'Fertilizer dose calculator per crop and per acre', 'Weather forecast integration (free API) with rain alerts', 'Mandi (market) price trends for major crops', 'Voice questions in Urdu/Sindhi using speech-to-text', 'Simple mobile-first web interface'], ARRAY['Python', 'scikit-learn', 'Flask', 'Weather API', 'Web Speech API'], 'Hard', 12, ARRAY['https://github.com/Viraj-Mavani/smart_agriculture_system', 'https://github.com/spMohanty/PlantVillage-Dataset'], ARRAY['AI/ML', 'Agriculture', 'Mobile', 'Data'], 40),
  ('Pakistani Sign Language Translator', 4, 'FYP-grade (Sem 7–8)', 'Sem 7–8', 'A real-time system that recognizes Pakistani Sign Language gestures from a webcam and converts them into text and speech.', 'Pakistan has a large deaf community but very few interpreters; a translator for common signs helps at hospitals, banks and government offices.', ARRAY['Webcam gesture capture with hand-landmark tracking (MediaPipe)', 'Classifier (LSTM or Random Forest) trained on collected PSL gesture data', 'Real-time prediction with confidence display', 'Text-to-speech output in Urdu and English', 'Add-your-own-sign training mode', 'Works offline on a normal laptop'], ARRAY['Python', 'MediaPipe', 'TensorFlow or scikit-learn', 'OpenCV', 'pyttsx3 (text-to-speech)'], 'Hard', 12, ARRAY['https://github.com/Ap178/AI-Sign-Language-Translator', 'https://github.com/google-ai-edge/mediapipe'], ARRAY['AI/ML', 'Desktop', 'Accessibility'], 41),
  ('Multi-Vendor Marketplace for Local Artisans', 4, 'FYP-grade (Sem 7–8)', 'Sem 7–8', 'An online marketplace where Sindhi artisans (ajrak, rilli, pottery, embroidery) open their own shops and sell across the country.', 'Skilled artisans sell through middlemen at very low margins; their own online shops with direct orders mean fair prices and a much wider reach.', ARRAY['Seller registration with individual shop pages', 'Product listings with photos, stock and categories', 'Cart, checkout and order management', 'Order status tracking for buyers', 'Admin panel with commission and sales reports', 'Live auction option for special pieces (stretch goal)'], ARRAY['MongoDB', 'Express', 'React', 'Node.js (MERN)', 'Cloudinary (free tier)', 'Cash-on-delivery order flow'], 'Hard', 12, ARRAY['https://github.com/shamahoque/mern-marketplace'], ARRAY['Web', 'Business'], 42),
  ('Blockchain-Based Degree Verification System', 4, 'FYP-grade (Sem 7–8)', 'Sem 7–8', 'A system where universities register degree hashes on a blockchain so any employer can verify a degree''s authenticity within seconds.', 'Fake degrees are a recurring scandal in Pakistan and manual verification takes weeks; a hash stored on-chain makes forgery detectable instantly.', ARRAY['University issues a degree record and stores its hash in a smart contract', 'Employer verifies by entering the degree ID or scanning a QR code', 'Result shows genuine or revoked status without exposing private data', 'Revocation support for cancelled degrees', 'Student page listing their verified credentials', 'Deployed on a free testnet with full documentation'], ARRAY['Solidity', 'Hardhat', 'React + ethers.js', 'Sepolia testnet'], 'Hard', 12, ARRAY['https://github.com/FouadElOuafy/certificate-verification', 'https://github.com/ROBINMASH1/Tawtheeq'], ARRAY['Web', 'Blockchain', 'Education', 'Security'], 43)
